#include "pcma.h"
#include "v32_data.h"
#include "v32_qam.h"
#include <stdio.h>
static void pattern(uint8_t*x,size_t n,unsigned s){for(size_t i=0;i<n;i++){s=s*1664525u+1013904223u;x[i]=(uint8_t)(s>>24);}}
int main(void){enum{N=1024};uint8_t ab[N],ba[N],rab[N]={0},rba[N]={0};pattern(ab,N,9600);pattern(ba,N,9601);struct v32_data a,b;v32_data_init(&a,V32_STD_CALL,V32_STATE_A,V32_STATE_A);v32_data_init(&b,V32_STD_ANSWER,V32_STATE_A,V32_STATE_A);v32_data_write(&a,ab,N);v32_data_write(&b,ba,N);struct v32_qam la,lb;v32_qam_init(&la);v32_qam_init(&lb);size_t na=0,nb=0;int blocks=0;for(;blocks<1000&&(na<N||nb<N);blocks++){uint8_t sa[48],sb[48];for(int i=0;i<48;i++){sa[i]=v32_data_next_9600(&a);sb[i]=v32_data_next_9600(&b);}v32_qam_write(&la,sa,48);v32_qam_write(&lb,sb,48);int16_t xa[160],xb[160],ya[160],yb[160];uint8_t law[160];v32_qam_generate(&la,xa,160);v32_qam_generate(&lb,xb,160);pcma_encode_buffer(xa,law,160);pcma_decode_buffer(law,ya,160);pcma_encode_buffer(xb,law,160);pcma_decode_buffer(law,yb,160);v32_qam_receive(&la,yb,160);v32_qam_receive(&lb,ya,160);size_t ca=v32_qam_read(&la,sa,48),cb=v32_qam_read(&lb,sb,48);for(size_t i=0;i<ca;i++)v32_data_put_9600(&a,sa[i]);for(size_t i=0;i<cb;i++)v32_data_put_9600(&b,sb[i]);na+=v32_data_read(&b,rab+na,N-na);nb+=v32_data_read(&a,rba+nb,N-nb);}size_t errors=0;for(size_t i=0;i<N;i++){errors+=ab[i]!=rab[i];errors+=ba[i]!=rba[i];}printf("V.32 9600 nonredundant/PCMA: %zu/%d and %zu/%d bytes, %zu byte errors, %.1f B/s\n",na,N,nb,N,errors,N/(blocks*.02));return na==N&&nb==N&&!errors?0:1;}
